// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *StrategyAwardClient) MapCreateBulk(slice any, setFunc func(*StrategyAwardCreate, int)) *StrategyAwardCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &StrategyAwardCreateBulk{err: fmt.Errorf("calling to StrategyAwardClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*StrategyAwardCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &StrategyAwardCreateBulk{config: c.config, builders: builders}
}

