func (c *StrategyAwardClient) mutate(ctx context.Context, m *StrategyAwardMutation) (Value, error) {
	switch m.Op() {
	case OpCreate:
		return (&StrategyAwardCreate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdate:
		return (&StrategyAwardUpdate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdateOne:
		return (&StrategyAwardUpdateOne{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpDelete, OpDeleteOne:
		return (&StrategyAwardDelete{config: c.config, hooks: c.Hooks(), mutation: m}).Exec(ctx)
	default:
		return nil, fmt.Errorf("ent: unknown StrategyAward mutation op: %q", m.Op())
	}
}

// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		LotteryActivity, LotteryOrder, LotteryStrategy, StrategyAward []ent.Hook
	}
	inters struct {
		LotteryActivity, LotteryOrder, LotteryStrategy, StrategyAward []ent.Interceptor
	}
)
